/// @sort 32
uniform float A = 1.0;
/// @sort 32
uniform float3 V = float3(1.0, 2.0, 3.0);
// A local without an initializer is zero of its exact width in 1.x; the front end writes the zero (SynthesizedInitializers).
/// @name M_LpGZero
export void M_LpGZero(inout material Base)
{
    float3 Color = float3(0, 0, 0);
    float S = 0;
    float2 P = float2(0, 0);
    float3 Q = float3(0, 0, 0);
    float4 R = float4(0, 0, 0, 0);
    Color = Q + float3(S, P.x, R.a);
    Base.EmissiveColor = Color;
}
